PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,email_verified INTEGER NOT NULL DEFAULT 0,password_hash TEXT,google_sub TEXT UNIQUE,early_access INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS athletes (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted_at TEXT);
CREATE INDEX IF NOT EXISTS idx_athletes_user ON athletes(user_id);
CREATE TABLE IF NOT EXISTS races (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,athlete_id TEXT REFERENCES athletes(id) ON DELETE SET NULL,client_id TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,event_name TEXT NOT NULL,event_snapshot TEXT NOT NULL,started_at TEXT,finished_at TEXT,elapsed_ms INTEGER,private INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted_at TEXT,UNIQUE(user_id,client_id));
CREATE INDEX IF NOT EXISTS idx_races_owner ON races(user_id,updated_at);
CREATE TABLE IF NOT EXISTS race_splits (id TEXT PRIMARY KEY,race_id TEXT NOT NULL REFERENCES races(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,stage_name TEXT NOT NULL,cumulative_ms INTEGER NOT NULL CHECK(cumulative_ms>=0),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(race_id,ordinal));
CREATE TABLE IF NOT EXISTS race_corrections (id TEXT PRIMARY KEY,race_id TEXT NOT NULL REFERENCES races(id) ON DELETE CASCADE,split_id TEXT NOT NULL REFERENCES race_splits(id) ON DELETE CASCADE,old_ms INTEGER NOT NULL,new_ms INTEGER NOT NULL,reason TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS share_grants (id TEXT PRIMARY KEY,race_id TEXT NOT NULL REFERENCES races(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT,revoked_at TEXT);
CREATE TABLE IF NOT EXISTS feedback_outbox (id TEXT PRIMARY KEY,type TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,contact TEXT,page TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,delivered_at TEXT,last_error TEXT);
CREATE INDEX IF NOT EXISTS idx_feedback_pending ON feedback_outbox(delivered_at,next_attempt_at);
CREATE TABLE IF NOT EXISTS oauth_states (state_hash TEXT PRIMARY KEY,verifier_hash TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
